package com.ridex.location.config;
import org.junit.jupiter.api.Test; import org.springframework.data.redis.connection.RedisConnectionFactory; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.data.redis.serializer.StringRedisSerializer; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class RedisConfigTest { @Test void createsStringSerializedRedisTemplate(){RedisConnectionFactory factory=mock(RedisConnectionFactory.class);RedisTemplate<String,String> template=new RedisConfig().redisTemplate(factory);assertSame(factory,template.getConnectionFactory());assertInstanceOf(StringRedisSerializer.class,template.getKeySerializer());assertInstanceOf(StringRedisSerializer.class,template.getValueSerializer());assertInstanceOf(StringRedisSerializer.class,template.getHashKeySerializer());assertInstanceOf(StringRedisSerializer.class,template.getHashValueSerializer());} }
